import{_ as e,o as r,c as d,aB as o}from"./chunks/framework.B1IvnFrq.js";const y=JSON.parse('{"title":"Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference.md","filePath":"reference.md","lastUpdated":null}'),i={name:"reference.md"};function a(s,t,n,l,c,g){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="Reference" tabindex="-1">Reference <a class="header-anchor" href="#Reference" aria-label="Permalink to &quot;Reference {#Reference}&quot;">​</a></h1><p>This page summarizes the public API. Optional keyword defaults are documented in the guide pages when behavior matters.</p><h2 id="Core-Types" tabindex="-1">Core Types <a class="header-anchor" href="#Core-Types" aria-label="Permalink to &quot;Core Types {#Core-Types}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Type</th><th style="text-align:right;">Purpose</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Client</code></td><td style="text-align:right;">Active client connection with background reader, ping, and reconnect tasks.</td></tr><tr><td style="text-align:right;"><code>ConnectOptions</code></td><td style="text-align:right;">Keyword-backed connection configuration.</td></tr><tr><td style="text-align:right;"><code>ConnectionStatus</code></td><td style="text-align:right;">EnumX status namespace: <code>DISCONNECTED</code>, <code>CONNECTING</code>, <code>CONNECTED</code>, <code>RECONNECTING</code>, <code>DRAINING</code>, <code>CLOSED</code>.</td></tr><tr><td style="text-align:right;"><code>Msg</code></td><td style="text-align:right;">Received message with <code>subject</code>, <code>reply</code>, <code>data</code>, <code>headers</code>, and acknowledgement state.</td></tr><tr><td style="text-align:right;"><code>Headers</code></td><td style="text-align:right;">Alias for <code>Dict{String,Vector{String}}</code>.</td></tr><tr><td style="text-align:right;"><code>Subscription</code></td><td style="text-align:right;">Core subscription handle.</td></tr><tr><td style="text-align:right;"><code>Stats</code></td><td style="text-align:right;">Snapshot of message, byte, reconnect, error, and drop counters.</td></tr></tbody></table><h2 id="Core-Functions" tabindex="-1">Core Functions <a class="header-anchor" href="#Core-Functions" aria-label="Permalink to &quot;Core Functions {#Core-Functions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Function</th><th style="text-align:right;">Purpose</th></tr></thead><tbody><tr><td style="text-align:right;"><code>connect(url_or_urls=nothing; kwargs...)</code></td><td style="text-align:right;">Connect to one or more servers.</td></tr><tr><td style="text-align:right;"><code>publish(client, subject, data=nothing; reply=nothing, headers=nothing)</code></td><td style="text-align:right;">Publish a core message.</td></tr><tr><td style="text-align:right;"><code>subscribe(client, subject; queue=nothing, callback=nothing, max_msgs=0, ...)</code></td><td style="text-align:right;">Create a core subscription.</td></tr><tr><td style="text-align:right;"><code>next(sub; timeout=1.0)</code></td><td style="text-align:right;">Wait for the next message from a subscription.</td></tr><tr><td style="text-align:right;"><code>request(client, subject, data=nothing; timeout=1.0, headers=nothing)</code></td><td style="text-align:right;">Send a request and wait for one response.</td></tr><tr><td style="text-align:right;"><code>flush(client; timeout=10.0)</code></td><td style="text-align:right;">Wait until the server has processed previous commands.</td></tr><tr><td style="text-align:right;"><code>ping(client; timeout=10.0)</code></td><td style="text-align:right;">Alias for <code>flush</code>.</td></tr><tr><td style="text-align:right;"><code>unsubscribe(sub; max_msgs=0)</code></td><td style="text-align:right;">Unsubscribe immediately or after <code>max_msgs</code> additional messages.</td></tr><tr><td style="text-align:right;"><code>drain(sub; timeout=...)</code></td><td style="text-align:right;">Unsubscribe and wait for queued callback work.</td></tr><tr><td style="text-align:right;"><code>drain(client; timeout=...)</code></td><td style="text-align:right;">Drain subscriptions, flush, and close the client.</td></tr><tr><td style="text-align:right;"><code>close(client; throw_errors=false)</code></td><td style="text-align:right;">Close transports, tasks, subscriptions, and callbacks.</td></tr><tr><td style="text-align:right;"><code>new_inbox(client; prefix=...)</code></td><td style="text-align:right;">Generate a reply inbox subject.</td></tr><tr><td style="text-align:right;"><code>header(msg, key)</code></td><td style="text-align:right;">Return the first header value or <code>nothing</code>.</td></tr><tr><td style="text-align:right;"><code>headers(msg)</code></td><td style="text-align:right;">Return a copy of all message headers.</td></tr><tr><td style="text-align:right;"><code>status(client)</code></td><td style="text-align:right;">Return current <code>ConnectionStatus</code>.</td></tr><tr><td style="text-align:right;"><code>stats(client)</code></td><td style="text-align:right;">Return a <code>Stats</code> snapshot.</td></tr><tr><td style="text-align:right;"><code>connected_url(client)</code></td><td style="text-align:right;">Return the current server URL or <code>nothing</code>.</td></tr></tbody></table><h2 id="JetStream-Types" tabindex="-1">JetStream Types <a class="header-anchor" href="#JetStream-Types" aria-label="Permalink to &quot;JetStream Types {#JetStream-Types}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Type</th><th style="text-align:right;">Purpose</th></tr></thead><tbody><tr><td style="text-align:right;"><code>JetStreamContext</code></td><td style="text-align:right;">JetStream API context for a client.</td></tr><tr><td style="text-align:right;"><code>StreamConfig</code></td><td style="text-align:right;">Typed stream configuration.</td></tr><tr><td style="text-align:right;"><code>ConsumerConfig</code></td><td style="text-align:right;">Typed consumer configuration.</td></tr><tr><td style="text-align:right;"><code>StreamInfo</code></td><td style="text-align:right;">Stream info response with typed config, state, and raw data.</td></tr><tr><td style="text-align:right;"><code>ConsumerInfo</code></td><td style="text-align:right;">Consumer info response with typed config and raw data.</td></tr><tr><td style="text-align:right;"><code>PubAck</code></td><td style="text-align:right;">Publish acknowledgement with stream, sequence, duplicate, and domain.</td></tr><tr><td style="text-align:right;"><code>PullSubscription</code></td><td style="text-align:right;">Pull consumer handle.</td></tr><tr><td style="text-align:right;"><code>PushSubscription</code></td><td style="text-align:right;">Push consumer handle.</td></tr></tbody></table><h2 id="JetStream-Enums" tabindex="-1">JetStream Enums <a class="header-anchor" href="#JetStream-Enums" aria-label="Permalink to &quot;JetStream Enums {#JetStream-Enums}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Enum Namespace</th><th style="text-align:right;">Values</th></tr></thead><tbody><tr><td style="text-align:right;"><code>RetentionPolicy</code></td><td style="text-align:right;"><code>LIMITS</code>, <code>INTEREST</code>, <code>WORK_QUEUE</code></td></tr><tr><td style="text-align:right;"><code>StorageType</code></td><td style="text-align:right;"><code>FILE</code>, <code>MEMORY</code></td></tr><tr><td style="text-align:right;"><code>DiscardPolicy</code></td><td style="text-align:right;"><code>OLD</code>, <code>NEW</code></td></tr><tr><td style="text-align:right;"><code>StoreCompression</code></td><td style="text-align:right;"><code>NONE</code>, <code>S2</code></td></tr><tr><td style="text-align:right;"><code>PersistMode</code></td><td style="text-align:right;"><code>DEFAULT</code>, <code>ASYNC</code></td></tr><tr><td style="text-align:right;"><code>AckPolicy</code></td><td style="text-align:right;"><code>NONE</code>, <code>ALL</code>, <code>EXPLICIT</code></td></tr><tr><td style="text-align:right;"><code>DeliverPolicy</code></td><td style="text-align:right;"><code>ALL</code>, <code>LAST</code>, <code>NEW</code>, <code>BY_START_SEQUENCE</code>, <code>BY_START_TIME</code>, <code>LAST_PER_SUBJECT</code></td></tr><tr><td style="text-align:right;"><code>ReplayPolicy</code></td><td style="text-align:right;"><code>INSTANT</code>, <code>ORIGINAL</code></td></tr><tr><td style="text-align:right;"><code>PriorityPolicy</code></td><td style="text-align:right;"><code>NONE</code>, <code>OVERFLOW</code>, <code>PINNED_CLIENT</code></td></tr></tbody></table><h2 id="JetStream-Functions" tabindex="-1">JetStream Functions <a class="header-anchor" href="#JetStream-Functions" aria-label="Permalink to &quot;JetStream Functions {#JetStream-Functions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Function</th><th style="text-align:right;">Purpose</th></tr></thead><tbody><tr><td style="text-align:right;"><code>jetstream(client; prefix=&quot;$JS.API&quot;, timeout=5.0)</code></td><td style="text-align:right;">Create a JetStream context.</td></tr><tr><td style="text-align:right;"><code>js_publish(js, subject, data=nothing; timeout=..., stream=nothing, headers=nothing)</code></td><td style="text-align:right;">Publish and wait for a <code>PubAck</code>.</td></tr><tr><td style="text-align:right;"><code>publish_async(js, subject, data=nothing; kwargs...)</code></td><td style="text-align:right;">Start a JetStream publish in a Julia task.</td></tr><tr><td style="text-align:right;"><code>stream_create(js, config)</code></td><td style="text-align:right;">Create a stream from <code>StreamConfig</code> or <code>Dict</code>.</td></tr><tr><td style="text-align:right;"><code>stream_update(js, config)</code></td><td style="text-align:right;">Update a stream.</td></tr><tr><td style="text-align:right;"><code>stream_info(js, name)</code></td><td style="text-align:right;">Fetch stream info.</td></tr><tr><td style="text-align:right;"><code>stream_list(js; offset=0)</code></td><td style="text-align:right;">List streams, following pagination.</td></tr><tr><td style="text-align:right;"><code>stream_names(js; subject=nothing)</code></td><td style="text-align:right;">List stream names, optionally filtered by subject.</td></tr><tr><td style="text-align:right;"><code>stream_purge(js, name; filter_subject=nothing)</code></td><td style="text-align:right;">Purge a stream or subject subset.</td></tr><tr><td style="text-align:right;"><code>stream_delete(js, name)</code></td><td style="text-align:right;">Delete a stream.</td></tr><tr><td style="text-align:right;"><code>stream_message_get(js, stream; seq=nothing, subject=nothing, direct=false, next_by_subject=false)</code></td><td style="text-align:right;">Read a stored message.</td></tr><tr><td style="text-align:right;"><code>stream_message_delete(js, stream, seq)</code></td><td style="text-align:right;">Delete one stored message.</td></tr><tr><td style="text-align:right;"><code>consumer_create(js, stream, config)</code></td><td style="text-align:right;">Create a consumer from <code>ConsumerConfig</code> or <code>Dict</code>.</td></tr><tr><td style="text-align:right;"><code>consumer_update(js, stream, config)</code></td><td style="text-align:right;">Update a consumer.</td></tr><tr><td style="text-align:right;"><code>consumer_info(js, stream, consumer)</code></td><td style="text-align:right;">Fetch consumer info.</td></tr><tr><td style="text-align:right;"><code>consumer_list(js, stream; offset=0)</code></td><td style="text-align:right;">List consumers for a stream.</td></tr><tr><td style="text-align:right;"><code>consumer_delete(js, stream, consumer)</code></td><td style="text-align:right;">Delete a consumer.</td></tr><tr><td style="text-align:right;"><code>pull_subscribe(js, subject; stream=nothing, durable=nothing, config=ConsumerConfig())</code></td><td style="text-align:right;">Create a pull subscription.</td></tr><tr><td style="text-align:right;"><code>push_subscribe(js, subject; stream=nothing, durable=nothing, queue=nothing, callback=nothing, manual_ack=false, config=ConsumerConfig())</code></td><td style="text-align:right;">Create a push subscription.</td></tr><tr><td style="text-align:right;"><code>fetch(psub, batch=1; timeout=..., expires=timeout)</code></td><td style="text-align:right;">Fetch a batch from a pull subscription.</td></tr><tr><td style="text-align:right;"><code>ack</code>, <code>ack_sync</code>, <code>nak</code>, <code>in_progress</code>, <code>term</code></td><td style="text-align:right;">Acknowledge or control redelivery for JetStream messages.</td></tr><tr><td style="text-align:right;"><code>metadata(msg)</code></td><td style="text-align:right;">Parse JetStream delivery metadata.</td></tr></tbody></table><h2 id="KeyValue-Functions" tabindex="-1">KeyValue Functions <a class="header-anchor" href="#KeyValue-Functions" aria-label="Permalink to &quot;KeyValue Functions {#KeyValue-Functions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Function</th><th style="text-align:right;">Purpose</th></tr></thead><tbody><tr><td style="text-align:right;"><code>kv_create(js, bucket; history=1, storage=&quot;file&quot;, replicas=1, direct=false)</code></td><td style="text-align:right;">Create a bucket.</td></tr><tr><td style="text-align:right;"><code>kv_open(js, bucket)</code></td><td style="text-align:right;">Open an existing bucket.</td></tr><tr><td style="text-align:right;"><code>kv_delete_bucket(kv)</code></td><td style="text-align:right;">Delete a bucket.</td></tr><tr><td style="text-align:right;"><code>kv_get(kv, key; revision=nothing, direct=nothing)</code></td><td style="text-align:right;">Get the latest value or a revision.</td></tr><tr><td style="text-align:right;"><code>kv_put(kv, key, value; revision=nothing)</code></td><td style="text-align:right;">Put a value, optionally expecting a revision.</td></tr><tr><td style="text-align:right;"><code>kv_create_key(kv, key, value)</code></td><td style="text-align:right;">Put a value only if the key is absent.</td></tr><tr><td style="text-align:right;"><code>kv_update(kv, key, value, revision)</code></td><td style="text-align:right;">Put a value only if the key is at <code>revision</code>.</td></tr><tr><td style="text-align:right;"><code>kv_delete(kv, key)</code></td><td style="text-align:right;">Mark a key deleted.</td></tr><tr><td style="text-align:right;"><code>kv_purge(kv, key)</code></td><td style="text-align:right;">Purge a key with rollup.</td></tr><tr><td style="text-align:right;"><code>kv_history(kv, key; batch=256)</code></td><td style="text-align:right;">Return historical messages for a key.</td></tr><tr><td style="text-align:right;"><code>kv_keys(kv)</code></td><td style="text-align:right;">Return active keys.</td></tr><tr><td style="text-align:right;"><code>kv_watch(callback, kv; key=&quot;&gt;&quot;, history=false)</code></td><td style="text-align:right;">Watch bucket updates with a push subscription.</td></tr></tbody></table><h2 id="Errors" tabindex="-1">Errors <a class="header-anchor" href="#Errors" aria-label="Permalink to &quot;Errors {#Errors}&quot;">​</a></h2><p>Public error types derive from <code>NatterError</code>: <code>TimeoutError</code>, <code>NoRespondersError</code>, <code>ConnectionClosedError</code>, <code>ConnectionReconnectingError</code>, <code>ConnectionDrainingError</code>, <code>ProtocolError</code>, <code>AuthorizationError</code>, <code>NoServersError</code>, <code>MaxPayloadError</code>, <code>OutboundBufferLimitError</code>, <code>SlowConsumerError</code>, <code>JetStreamError</code>, <code>UnsupportedFeatureError</code>, and <code>CleanupError</code>.</p>',16)])])}const u=e(i,[["render",a]]);export{y as __pageData,u as default};
